package com.xdownload.mobile;
import java.util.Locale;
/** User-facing diagnostics never echo raw extractor output, URLs, tokens or headers. */
final class DownloadErrors{
 static String classify(Throwable error){StringBuilder b=new StringBuilder();for(int i=0;error!=null&&i<5;i++,error=error.getCause())b.append(' ').append(error.getClass().getSimpleName()).append(' ').append(error.getMessage());String m=b.toString().toLowerCase(Locale.ROOT);if(m.contains("drm")||m.contains("protected media"))return "protected";if(m.contains("storage")||m.contains("no space")||m.contains("disk full"))return "storage";if(m.contains("folder permission")||m.contains("permission revoked"))return "folder";if(m.contains("429")||m.contains("too many requests"))return "rate";if(m.contains("javascript")||m.contains("challenge")||m.contains("runtime unavailable")||m.contains("extractor runtime"))return "runtime";if(m.contains("sign in")||m.contains("login")||m.contains("401")||m.contains("403")||m.contains("410")||m.contains("expired"))return "access";if(m.contains("404")||m.contains("not found")||m.contains("unavailable")&&m.contains("video"))return "missing";if(m.contains("timeout")||m.contains("timed out")||m.contains("network")||m.contains("unknownhost")||m.contains("connection")||m.contains("unable to download"))return "network";if(m.contains("checksum")||m.contains("hash mismatch")||m.contains("sha-256"))return "integrity";if(m.contains("remote file changed")||m.contains("range")||m.contains("etag"))return "range";if(m.contains("ffmpeg")||m.contains("output format")||m.contains("format")||m.contains("codec"))return "format";if(m.contains("ssl")||m.contains("certificate")||m.contains("tls"))return "tls";return "unknown";}
 static String message(Throwable e,boolean en){switch(classify(e)){case "protected":return en?"Protected content is not supported. Use the official service.":"المحتوى محمي. استخدم الخدمة الرسمية.";case "folder":return en?"Download folder access was revoked. Select a writable folder and resume.":"صلاحية مجلد التنزيل ملغاة. اختر مجلدًا قابلًا للكتابة واستكمل.";case "storage":return en?"Not enough free space. Free storage and resume.":"المساحة غير كافية. وفر مساحة واستكمل.";case "rate":return en?"The server is limiting requests. Try later or reduce connections.":"الخادم يحد الطلبات. حاول لاحقًا أو قلل الاتصالات.";case "runtime":return en?"The source requires an updated compatible extractor. Check engine updates; use official access if unavailable.":"المصدر يحتاج محرك استخراج متوافقًا. تحقق من تحديث المحرك أو استخدم الخدمة الرسمية.";case "access":return en?"Source denied access or link expired. Obtain a fresh authorized link.":"المصدر رفض الوصول أو انتهى الرابط. احصل على رابط مصرح به جديد.";case "missing":return en?"The file or video is no longer available at this address.":"الملف أو الفيديو غير متاح بهذا العنوان.";case "network":return en?"Connection interrupted. Check the network and resume.":"انقطع الاتصال. تحقق من الشبكة واستكمل.";case "integrity":return en?"File integrity check failed. Do not open the partial file.":"فشل التحقق من سلامة الملف. لا تفتح الملف الناقص.";case "range":return en?"Source changed or does not support safe range resume. Retry with one connection.":"تغير المصدر أو لا يدعم الاستكمال الآمن. جرب اتصالًا واحدًا.";case "format":return en?"The selected format could not be produced. Reanalyze and select another available format.":"تعذر إنتاج الصيغة المختارة. أعد التحليل واختر صيغة متاحة أخرى.";case "tls":return en?"Secure connection could not be verified. Check the server certificate and device date.":"تعذر التحقق من الاتصال الآمن. تحقق من شهادة الخادم وتاريخ الجهاز.";default:return en?"No authorized downloadable file could be obtained. Retry or open the source.":"تعذر الحصول على ملف مصرح بتنزيله. أعد المحاولة أو افتح المصدر.";}}
}